import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers } from 'kea'

import { emailTemplaterLogic } from 'scenes/hog-functions/email-templater/emailTemplaterLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface emailHtmlViewLogicValues {
    reading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface emailHtmlViewLogicActions {
    designUpdated: () => {
        value: true
    } // emailTemplaterLogic
    latestEditRead: () => {
        value: true
    }
    readLatestEdit: () => {
        value: true
    }
}

export type emailHtmlViewLogicType = MakeLogicType<emailHtmlViewLogicValues, emailHtmlViewLogicActions>

/** Follows a save: it hands over the canvas's last edit the same way, so the email's html is what a save stores. */
export const emailHtmlViewLogic = kea<emailHtmlViewLogicType>([
    path(['products', 'workflows', 'frontend', 'EmailDocumentEditor', 'emailHtmlViewLogic']),
    connect(() => ({
        actions: [emailTemplaterLogic, ['designUpdated']],
    })),
    actions({
        readLatestEdit: true,
        latestEditRead: true,
    }),
    reducers({
        reading: [
            true,
            {
                readLatestEdit: () => true,
                latestEditRead: () => false,
            },
        ],
    }),
    listeners(({ actions }) => ({
        // An image that finishes uploading can still change the email while this is open.
        designUpdated: () => actions.readLatestEdit(),
        readLatestEdit: async (_, breakpoint) => {
            await emailTemplaterLogic.findMounted()?.asyncActions.flushPendingDesignEdit()
            breakpoint()
            actions.latestEditRead()
        },
    })),
    afterMount(({ actions }) => {
        actions.readLatestEdit()
    }),
])
